export const LEFT = 'a'.repeat(32), RIGHT = 'b'.repeat(32), THIRD = 'c'.repeat(32)
export const revision = 'd'.repeat(64)
export const candidates = (ids = ['sim_A', 'sim_B']) => ({ candidates: ids.map(simulation_id => ({ simulation_id, scenario: `Scenario ${simulation_id}`, status: 'completed', updated_at: '2026-10-01T10:00:00Z' })), skipped_records: 0 })
export const preview = (simulation_id = 'sim_A', count = 3) => ({ schema_version: 1, source_revision: revision, observed_at: '2026-10-03T12:00:00Z', summary: {
  simulation_id, project_id: 'project', graph_id: 'graph', scenario: `Scenario ${simulation_id}`, configured_model: 'saved-model', configured_agents: '10', status: 'completed', requested_rounds: '20', last_saved_round: '8',
  created_at: '2026-10-01T09:00:00Z', updated_at: '2026-10-01T10:00:00Z', started_at: '2026-10-01T09:01:00Z', completed_at: '2026-10-01T10:00:00Z', availability: 'complete', warnings: [],
  metrics: { recorded_actions: count, rounds_with_actions: 2, platforms: { twitter: { availability: 'complete', recorded_actions: count, active_agents: 2 }, reddit: { availability: 'unavailable', recorded_actions: null, active_agents: null } }, action_types: [{ action_type: 'POST', count }] }
} })
export const capture = (capture_id = LEFT, simulation_id = 'sim_A', count = 3, label = 'First attempt', note = '') => ({ schema_version: 1, capture_id, label, note, captured_at: '2026-10-03T12:01:00Z', observation: preview(simulation_id, count) })
export const library = (records = [capture()], offset = 0, total = records.length) => ({ captures: records.map(item => ({ capture_id: item.capture_id, simulation_id: item.observation.summary.simulation_id, label: item.label, captured_at: item.captured_at, status: item.observation.summary.status, availability: item.observation.summary.availability })), offset, limit: 20, total, has_more: offset + records.length < total })
export const comparison = (left = capture(), right = capture(RIGHT, 'sim_A', 5, 'Second attempt')) => ({ schema_version: 1, left, right, generated_at: '2026-10-03T12:02:00Z', differences: { recorded_actions: right.observation.summary.metrics.recorded_actions - left.observation.summary.metrics.recorded_actions, rounds_with_actions: 0, platforms: { twitter: { recorded_actions: 2, active_agents: 0 }, reddit: { recorded_actions: null, active_agents: null } }, action_types: [{ action_type: 'POST', left: 3, right: 5, difference: 2 }] } })
